CREATE FUNCTION pg_temp.fail_evidence_audit() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.event_type='work_order.evidence_saved' THEN RAISE EXCEPTION 'Synthetic audit failure' USING ERRCODE='23514'; END IF; RETURN NEW; END $$;
CREATE TRIGGER synthetic_evidence_audit_failure BEFORE INSERT ON public.audit_events FOR EACH ROW EXECUTE FUNCTION pg_temp.fail_evidence_audit();
